/**
 * Contentsquare Adapter
 *
 * Adapts standardized event payloads into Contentsquare format.
 *
 * @see https://docs.contentsquare.com/en/web/ecommerce-tag/
 * @see https://docs.contentsquare.com/en/web/sending-ecommerce-commands/
 * @see https://docs.contentsquare.com/en/web/sending-an-add-to-cart/
 */

(function (wpm, $, undefined) {

	class ContentsquareAdapter {

		/**
		 * Adapt an event for Contentsquare
		 * @param {Object} eventData - Standardized event data
		 * @param {string} eventName - Standardized event name
		 * @param {Object} context - Additional context
		 * @returns {Object|null} - Contentsquare formatted event or null to skip
		 */
		adapt(eventData, eventName, context) {
			const methodName = `adapt${this.toPascalCase(eventName)}`;

			if (typeof this[methodName] === "function") {
				return this[methodName](eventData, context);
			}

			// Default adaptation for unsupported events
			return null;
		}

		toPascalCase(str) {
			if (typeof str !== "string") return "";
			return str.replace(/(^|_)(\w)/g, (_, __, c) => c.toUpperCase());
		}

		/**
		 * Adapt AddToCart event
		 */
		adaptAddToCart(eventData, context) {
			return {
				event_type: "add_to_cart",
				sku: eventData.product?.sku || eventData.product?.id,
				merchant: window.location.hostname,
			};
		}

		/**
		 * Adapt Purchase event
		 */
		adaptPurchase(eventData, context) {
			const items = Object.values(wpmDataLayer?.order?.items || {}).map(item => ({
				id: wpmDataLayer?.order?.id?.toString(),
				sku: item.sku || item.id?.toString(),
				price: item.price?.toString(),
				quantity: item.quantity?.toString(),
				name: item.name,
				category: item.category?.join(" > ") || "",
			}));

			const revenue = Math.round(Number(wpmDataLayer?.order?.value?.total) * 100) / 100;

			return {
				event_type: "transaction",
				transaction: {
					id: wpmDataLayer?.order?.id?.toString(),
					revenue: revenue,
					currency: wpmDataLayer?.order?.currency?.toLowerCase(),
				},
				items: items,
			};
		}
	}

	// Register the adapter with capabilities
	const adapter = new ContentsquareAdapter();
	wpm.registerAdapter("contentsquare", adapter, {
		supportsS2S: false,
		supportsEventDeduplication: false,
		isActive: () => wpmDataLayer?.pixels?.contentsquare?.tag_id ? true : false,
	});

}(window.wpm = window.wpm || {}, jQuery));
