/**
 * Contentsquare Functions
 *
 * @see https://docs.contentsquare.com/en/web/
 * @see https://docs.contentsquare.com/en/web/ecommerce-tag/
 */

(function (wpm, $, undefined) {

	/**
	 * Load the Contentsquare pixel
	 */
	wpm.loadContentsquarePixel = () => {
		try {
			// Initialize Contentsquare global array
			window._uxa = window._uxa || [];

			// Load the Contentsquare main tag script
			let script = document.createElement("script");
			script.type = "text/javascript";
			script.async = true;
			script.src = "https://t.contentsquare.net/uxa/" + wpmDataLayer.pixels.contentsquare.tag_id + ".js";

			let firstScript = document.getElementsByTagName("script")[0];
			firstScript.parentNode.insertBefore(script, firstScript);

			wpmDataLayer.pixels.contentsquare.loaded = true;

			pmw.console.log("Contentsquare: pixel loaded");

		} catch (e) {
			console.error(e);
		}
	};

	/**
	 * Track add to cart event
	 *
	 * @param {Object} contentsquareData - Adapted Contentsquare data from event payload
	 * @see https://docs.contentsquare.com/en/web/sending-an-add-to-cart/
	 */
	wpm.contentsquareTrackAddToCart = (contentsquareData) => {
		try {
			window._uxa = window._uxa || [];

			let data = {
				sku: contentsquareData.sku?.toString(),
				merchant: contentsquareData.merchant,
			};

			// Track page event for add to cart
			window._uxa.push(["trackPageEvent", "addToCart"]);

			// Send add to cart data
			window._uxa.push(["ec:cart:add", data]);

			pmw.console.log("Contentsquare: add_to_cart event sent", data);

		} catch (e) {
			console.error(e);
		}
	};

	/**
	 * Track transaction/purchase event
	 *
	 * @param {Object} contentsquareData - Adapted Contentsquare data from event payload
	 * @see https://docs.contentsquare.com/en/web/sending-ecommerce-commands/
	 */
	wpm.contentsquareTrackTransaction = (contentsquareData) => {
		try {
			window._uxa = window._uxa || [];

			// Create transaction with id, revenue, currency
			window._uxa.push(["ec:transaction:create", contentsquareData.transaction]);

			// Add individual items (for Merchandising support)
			// Each item needs: id, sku, price, quantity, name, category (optional)
			for (let item of contentsquareData.items) {
				window._uxa.push(["ec:transaction:items:add", item]);
			}

			// Send transaction to Contentsquare
			window._uxa.push(["ec:transaction:send"]);

			pmw.console.log("Contentsquare: purchase event sent", contentsquareData);

		} catch (e) {
			console.error(e);
		}
	};

}(window.wpm = window.wpm || {}, jQuery));
