/**
 * Contentsquare Event Listeners
 *
 * @see https://docs.contentsquare.com/en/web/ecommerce-tag/
 * @see https://docs.contentsquare.com/en/web/sending-ecommerce-commands/
 * @see https://docs.contentsquare.com/en/web/sending-an-add-to-cart/
 */

(function (wpm, $, undefined) {

	/**
	 * Load pixel on consent
	 */
	jQuery(document).on("pmw:load-pixels", function () {
		if (
			wpmDataLayer?.pixels?.contentsquare?.tag_id &&
			!wpmDataLayer?.pixels?.contentsquare?.loaded &&
			wpm.consent.canPixelBeFired("statistics", "Contentsquare")
		) {
			wpm.loadContentsquarePixel();
		}
	});

	/**
	 * Add to Cart event
	 *
	 * Fires when a product is added to the cart.
	 */
	jQuery(document).on("pmw:browser:add-to-cart", (event, payload) => {
		if (!wpmDataLayer?.pixels?.contentsquare?.loaded) return;

		try {
			const contentsquareData = payload.pixels?.contentsquare;
			if (!contentsquareData) return;

			wpm.contentsquareTrackAddToCart(contentsquareData);
		} catch (e) {
			console.error(e);
		}
	});

	/**
	 * Purchase/Order Received event
	 *
	 * Fires when a purchase is completed and the order received page is viewed.
	 */
	jQuery(document).on("pmw:browser:purchase", (event, payload) => {
		if (!wpmDataLayer?.pixels?.contentsquare?.loaded) return;

		try {
			const contentsquareData = payload.pixels?.contentsquare;
			if (!contentsquareData) return;

			wpm.contentsquareTrackTransaction(contentsquareData);
		} catch (e) {
			console.error(e);
		}
	});

}(window.wpm = window.wpm || {}, jQuery));
